/** The canonical specialist-to-editor writer. Receipts, project visits and
 * signed-in account scope are confirmed before content or navigation proceeds. */
import { apiRequest, ApiRequestError, redactInternals, serverMessage } from '@/lib/queryClient';
import { authService } from '@/services/portal/authService';
import { unboundNotice } from './governanceNotice';
import { captureShellProjectGuard, shellProgramId } from './shellProject';
import { setEditorTarget } from './editorTarget';
import { useAuthoringHandoffController } from './authoringHandoffRecovery';
import { hasAuthoringCreationOutcome, readAuthoringCreationRecovery, type AuthoringCreationRecoveryIdentity } from './editor/authoringCreationRecovery';
export type { AuthoringHandoffController, AuthoringHandoffRecoveryState } from './authoringHandoffRecovery';

export interface AuthoringHandoff {
  title: string;
  /** The specialist states its own CTD module; the server otherwise defaults to M3. */
  module: string;
  /** A working identifier, never a guessed CTD filing location. */
  code: string;
  content: string;
  subject: string;
}
export interface HandoffContext {
  programId: string | null;
  code: string;
  isCurrent: () => boolean;
}
export type AuthoringHandoffResult = HandoffContext & (
  | { ok: true; docId: string; programId: string; bound: boolean | null; message: string; reused?: boolean }
  | { ok: false; phase: 'refused' | 'unknown' | 'partial' | 'stale' | 'blocked'; docId?: string; message: string }
);
type StageResult =
  | { phase: 'confirmed'; body: Record<string, unknown>; row: Record<string, unknown> }
  | { phase: 'refused' | 'unknown' | 'stale'; message?: string; recovery?: AuthoringCreationRecoveryIdentity };
const nonempty = (value: unknown): value is string => typeof value === 'string' && Boolean(value.trim());
const record = (value: unknown): Record<string, unknown> | null =>
  value !== null && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : null;

function captureHandoffContext(code: string, mounted: () => boolean): HandoffContext {
  const programId = shellProgramId();
  const projectCurrent = captureShellProjectGuard();
  const session = authService.captureSessionReadGuard();
  const account = authService.getUser();
  const actor = `${account?.organizationId ?? ''}:${account?.id ?? ''}`;
  return { programId, code, isCurrent: () => mounted() && projectCurrent() && session.sameRevision()
    && `${authService.getUser()?.organizationId ?? ''}:${authService.getUser()?.id ?? ''}` === actor };
}

function confirmedStage(kind: 'document' | 'section', raw: unknown, request: Record<string, unknown>): StageResult {
  const body = record(raw);
  const row = record(body?.[kind]);
  if (body?.success !== true || !row || !nonempty(row.id) || typeof row.title !== 'string') return { phase: 'unknown' };
  const matches = kind === 'document' ? row.client_program_id === request.client_program_id
    : row.doc_id === request.doc_id && row.code === request.code;
  return matches ? { phase: 'confirmed', body, row } : { phase: 'unknown' };
}

async function writeHandoffStage(kind: 'document' | 'section', request: Record<string, unknown>, current: () => boolean): Promise<StageResult> {
  try {
    const response = await apiRequest('POST', kind === 'document' ? '/api/authoring/docs' : '/api/authoring/sections', request);
    if (!current()) return { phase: 'stale' };
    const body: unknown = await response.json().catch(() => null);
    if (!current()) return { phase: 'stale' };
    if (kind === 'document' && hasAuthoringCreationOutcome(body)) return recoveryStage(body, request);
    if (!response.ok) return { phase: response.status >= 400 && response.status < 500 ? 'refused' : 'unknown', message: response.status === 401 ? 'your session isn’t authenticated' : serverMessage(body) ?? undefined };
    return confirmedStage(kind, body, request);
  } catch (error) {
    if (!current()) return { phase: 'stale' };
    if (kind === 'document' && error instanceof ApiRequestError && hasAuthoringCreationOutcome(error.payload)) return recoveryStage(error.payload, request);
    return error instanceof ApiRequestError && error.status >= 400 && error.status < 500
      ? { phase: 'refused', message: redactInternals(error.message, 'The server refused this write.') } : { phase: 'unknown' };
  }
}

function recoveryStage(body: unknown, request: Record<string, unknown>): StageResult {
  const recovery = readAuthoringCreationRecovery(body, authService.getUser()?.organizationId,
    typeof request.client_program_id === 'string' ? request.client_program_id : null);
  return { phase: 'unknown', ...(recovery ? { recovery } : {}) };
}

function failedHandoff(context: HandoffContext, result: Exclude<StageResult, { phase: 'confirmed' }>, subject: string, docId?: string): AuthoringHandoffResult {
  if (result.recovery && !docId) return { ...context, ok: false, phase: 'unknown', docId: result.recovery.documentId,
    message: `Document ${result.recovery.documentId}: ${result.recovery.creationOutcome === 'committed' ? 'creation committed, but its current handoff could not be confirmed' : 'creation outcome is unconfirmed'}. Check this exact document in its original project before continuing. Do not retry creation; ${subject} is still here.` };
  const known = docId ? `Document ${docId} was created, but its text` : 'The document';
  if (result.phase === 'stale') return { ...context, ok: false, phase: 'stale', ...(docId ? { docId } : {}),
    message: 'The project or signed-in account changed while the handoff was running. Check working documents in the original project before creating another copy.' };
  if (result.phase === 'refused') return { ...context, ok: false, phase: docId ? 'partial' : 'refused', ...(docId ? { docId } : {}),
    message: docId ? `${known} did not save — ${result.message ?? 'the server refused the text write'}. Staying here so you do not lose ${subject}. Check that document before retrying.`
      : `Couldn’t create the document — ${result.message ?? 'the server refused it'}. Nothing was saved; ${subject} is still here.` };
  return { ...context, ok: false, phase: 'unknown', ...(docId ? { docId } : {}),
    message: docId ? `${known} save could not be confirmed. Check that document in the original project before creating another copy; ${subject} is still here.`
      : `Could not confirm whether the document was saved. Check working documents in the original project before creating another copy; ${subject} is still here.` };
}

function bindingOutcome(body: Record<string, unknown>): boolean | null {
  const governance = record(body.governance);
  if (governance?.bound === false) return false;
  return governance?.bound === true && nonempty(governance.c2cDocumentId) ? true : null;
}

/** No automatic retry: a missing response can follow a committed write. The
 * existing two-request path can leave a document without a confirmed section. */
export async function saveToAuthoring(h: AuthoringHandoff, mounted: () => boolean = () => true): Promise<AuthoringHandoffResult> {
  const context = captureHandoffContext(h.code, mounted);
  if (!context.programId) return { ...context, ok: false, phase: 'refused',
    message: `Not opened — open a project first: a document belongs to a project. Nothing was saved; ${h.subject} is still here.` };
  if (!context.isCurrent()) return failedHandoff(context, { phase: 'stale' }, h.subject);
  const created = await writeHandoffStage('document', {
    title: h.title, module: h.module, client_program_id: context.programId,
  }, context.isCurrent);
  if (created.phase !== 'confirmed') return failedHandoff(context, created, h.subject);
  const docId = String(created.row.id);
  if (!context.isCurrent()) return failedHandoff(context, { phase: 'stale' }, h.subject, docId);
  const saved = await writeHandoffStage('section', {
    doc_id: docId, code: h.code, title: h.title, content: h.content,
  }, context.isCurrent);
  if (saved.phase !== 'confirmed') return failedHandoff(context, saved, h.subject, docId);
  if (!context.isCurrent()) return failedHandoff(context, { phase: 'stale' }, h.subject, docId);
  return { ...context, ok: true, programId: context.programId, docId, bound: bindingOutcome(created.body),
    message: `Saved to the authoring store as “${h.title}” — open Document authoring to edit it.` + unboundNotice(created.body.governance) };
}

/** Explicit continuation into an already confirmed document; callers verify
 * its current project membership and section inventory before invoking it. */
async function continueAuthoringText(h: AuthoringHandoff, context: HandoffContext, docId: string): Promise<AuthoringHandoffResult> {
  if (!context.isCurrent()) return failedHandoff(context, { phase: 'stale' }, h.subject, docId);
  const saved = await writeHandoffStage('section', { doc_id: docId, code: h.code, title: h.title, content: h.content }, context.isCurrent);
  if (saved.phase !== 'confirmed') return failedHandoff(context, saved, h.subject, docId);
  return { ...context, ok: true, programId: context.programId!, docId, bound: null,
    message: `Text saved to the existing working document “${h.title}”. Filing binding was not rechecked.` };
}

/** All specialist actions in this mounted owner share one attempt lane. */
export function useAuthoringHandoff() {
  return useAuthoringHandoffController({ save: saveToAuthoring, capture: captureHandoffContext, continueText: continueAuthoringText });
}

/** Use the existing exact-target channel; a stale receipt never changes it. */
export function openSavedAuthoring(result: AuthoringHandoffResult, onNav: (id: string) => void): boolean {
  if (!result.ok || !result.isCurrent()) return false;
  setEditorTarget({ docType: null, docId: result.docId, programId: result.programId, code: result.code });
  onNav('document-authoring');
  return true;
}

export type { WorkflowImportSource } from '@shared/authoring/source-import';
import type { AuthoringImportOrigin, AuthoringImportSource, AuthoringSourceImportData, AuthoringSourceImportPreviewData,
  BinaryImportOrigin, BinaryImportSource, WorkflowImportOrigin, WorkflowImportSource } from '@shared/authoring/source-import';
import { agencyResponseImportId, studyDesignImportId } from '@shared/authoring/source-import';
import { stableStringify } from '@shared/canonical-json';
import { authoringCurrentReadPath } from './editor/authoringCurrentRead';

export type SourceImportResult = AuthoringSourceImportData;
export interface SourceIntakeRequest {
  actor: { userId: number; organizationId: number };
  headers: Record<string, string>;
  current: () => boolean;
}
export interface SourceIntakeFailure {
  ok: false;
  phase: 'refused' | 'unknown' | 'stale';
  message: string;
  recovery?: AuthoringCreationRecoveryIdentity;
  identifiedOutcome?: boolean;
}
export type SourceIntakeReply<T> = { ok: true; data: T } | SourceIntakeFailure;
export interface SourceImportInspectionAttempt {
  preview?: AuthoringSourceImportPreviewData;
  recovery?: AuthoringCreationRecoveryIdentity;
  identifiedOutcome?: boolean;
}
export type SourceImportInspection = { ok: true; inventory: Array<{ id: string; title: string }>; data?: SourceImportResult } | SourceIntakeFailure;

export function isWorkflowSource(source: unknown): source is WorkflowImportSource {
  if (!source || typeof source !== 'object') return false;
  const kind = (source as { kind?: unknown }).kind;
  return kind === 'protocol' || kind === 'csr' || kind === 'ivd-assessment' || kind === 'ivd-document' || kind === 'study-design-crf' || kind === 'agency-response';
}

/** Stable selection identity; ordering does not change a CSR selection. */
export function workflowSourceKey(source: WorkflowImportSource): string {
  if (source.kind === 'agency-response') return `agency-response:${agencyResponseImportId(source.eventId, source.questionId) ?? 'invalid-selection'}`;
  if (source.kind === 'study-design-crf') return `${source.kind}:${source.studyId}`;
  if (source.kind !== 'csr') return `${source.kind}:${source.documentId}`;
  if (source.sectionNumbers !== undefined && (!Array.isArray(source.sectionNumbers) || !source.sectionNumbers.every(s => typeof s === 'string'))) return 'invalid-selection';
  return `csr:${source.jobId}:${[...new Set(source.sectionNumbers?.map(s => s.trim()) ?? [])].sort().join(',')}`;
}
const importHash = (value: unknown): value is string => typeof value === 'string' && /^[a-f0-9]{64}$/i.test(value);
const importUuid = (value: unknown): value is string => typeof value === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value);
const importInteger = (value: unknown): value is number => Number.isSafeInteger(value) && Number(value) > 0 && Number(value) <= 2147483647;
const stringList = (value: unknown): value is string[] => Array.isArray(value) && value.every(s => typeof s === 'string');
const nullableText = (value: unknown): boolean => value === null || typeof value === 'string';
const nullableUuid = (value: unknown): boolean => value === null || importUuid(value);
const nullableInteger = (value: unknown): boolean => value === null || importInteger(value);
const uniqueCodes = (rows: Array<{ code: string }>): boolean => new Set(rows.map(row => row.code.trim().toUpperCase())).size === rows.length;

function validWorkflowSource(source: unknown): source is WorkflowImportSource {
  if (!isWorkflowSource(source)) return false;
  if (source.kind === 'agency-response') return agencyResponseImportId(source.eventId, source.questionId) !== null;
  if (source.kind === 'study-design-crf') return nonempty(source.studyId) && studyDesignImportId(source.studyId) === source.studyId;
  if (source.kind === 'protocol') return importInteger(source.documentId);
  if (source.kind !== 'csr') return importUuid(source.documentId);
  return importInteger(source.jobId) && (source.sectionNumbers === undefined || (Array.isArray(source.sectionNumbers)
    && source.sectionNumbers.length > 0 && source.sectionNumbers.length <= 200 && source.sectionNumbers.every(nonempty)));
}
function validBinarySource(source: unknown): source is BinaryImportSource {
  const value = record(source);
  return value?.kind === 'vault' ? importUuid(value.documentId) : value?.kind === 'data-room' && importInteger(value.sourceId);
}
function validSectionOrigin(section: WorkflowImportOrigin['sectionOrigins'][number]): boolean {
  return !!section && nonempty(section.code) && importHash(section.contentSha256) && nonempty(section.sourceRowId)
    && ['machine', 'template', 'unknown'].includes(section.originalAuthorship)
    && ['unrecorded', 'recorded-name-only'].includes(section.modelEvidence) && nullableText(section.model);
}
const workflowConversions: Record<WorkflowImportSource['kind'], WorkflowImportOrigin['conversion']> = {
  'agency-response': 'agency-response-snapshot',
  'study-design-crf': 'study-design-crf-projection',
  protocol: 'protocol-structure', csr: 'ich-e3-sections', 'ivd-assessment': 'ivd-assessment-snapshot', 'ivd-document': 'ivd-document-snapshot',
};
function validWorkflowScope(origin: WorkflowImportOrigin): boolean {
  const scope = origin.sourceScope;
  return !!scope && ['organization', 'program', 'project'].includes(scope.level)
    && nullableUuid(scope.programId) && nullableInteger(scope.projectId);
}
function validWorkflowMetadata(origin: WorkflowImportOrigin): boolean {
  return nullableText(origin.version) && origin.documentType === null && origin.sectionCode === null
    && origin.conversion === workflowConversions[origin.kind] && validWorkflowScope(origin)
    && !!origin.association && ['recorded', 'explicit'].includes(origin.association.mode) && nullableText(origin.association.reason);
}
function validWorkflowOrigins(origin: WorkflowImportOrigin): boolean {
  return Array.isArray(origin.sectionOrigins) && origin.sectionOrigins.length > 0 && origin.sectionOrigins.every(validSectionOrigin)
    && uniqueCodes(origin.sectionOrigins) && stringList(origin.gaps) && validWorkflowMetadata(origin);
}
export function workflowOriginMatches(origin: WorkflowImportOrigin | undefined, programId: string, source: WorkflowImportSource | undefined): boolean {
  if (!origin || !importUuid(programId) || !validWorkflowSource(source) || origin.kind !== source.kind || origin.programId !== programId) return false;
  const id = source.kind === 'agency-response' ? agencyResponseImportId(source.eventId, source.questionId)
    : source.kind === 'csr' ? source.jobId : source.kind === 'study-design-crf' ? source.studyId : source.documentId;
  if (origin.id !== String(id) || !validWorkflowSource(origin.selection) || workflowSourceKey(origin.selection) !== workflowSourceKey(source)) return false;
  return importHash(origin.fingerprint) && nonempty(origin.title) && validWorkflowOrigins(origin);
}
function validPreviewSections(sections: AuthoringSourceImportPreviewData['sections']): boolean {
  return Array.isArray(sections) && sections.length > 0 && sections.every(s => !!s && nonempty(s.code)
    && typeof s.title === 'string' && importHash(s.contentSha256)) && uniqueCodes(sections);
}
function matchingPreviewScope(data: AuthoringSourceImportPreviewData, programId: string): boolean {
  const association = data.association;
  if (data.fingerprint !== data.origin.fingerprint || data.target?.programId !== programId || !importInteger(data.target.projectId)) return false;
  return !!association && association.targetProgramId === programId && association.mode === data.origin.association.mode
    && typeof association.required === 'boolean' && typeof association.reasonRequired === 'boolean'
    && nullableUuid(association.sourceProgramId) && nullableInteger(association.sourceProjectId);
}
export function readWorkflowPreview(body: unknown, programId: string, source: WorkflowImportSource): AuthoringSourceImportPreviewData | null {
  const envelope = body as { success?: boolean; data?: AuthoringSourceImportPreviewData } | null;
  const data = envelope?.data;
  if (envelope?.success !== true || !data || data.preview !== true || !workflowOriginMatches(data.origin, programId, source)) return null;
  if (!matchingPreviewScope(data, programId) || !validPreviewSections(data.sections) || !stringList(data.gaps) || !stringList(data.warnings)) return null;
  const origins = new Map(data.origin.sectionOrigins.map(section => [section.code.trim().toUpperCase(), section.contentSha256]));
  return origins.size === data.sections.length && data.sections.every(section => origins.get(section.code.trim().toUpperCase()) === section.contentSha256) ? data : null;
}
function validSavedSectionKeys(sections: AuthoringSourceImportData['sections']): boolean {
  if (!sections.every(s => !!s && importUuid(s.id) && nonempty(s.code))) return false;
  const ids = new Set(sections.map(s => String(s.id).toLowerCase()));
  const codes = new Set(sections.map(s => String(s.code).trim().toUpperCase()));
  return ids.size === sections.length && codes.size === sections.length;
}
function actualSavedSection(section: Record<string, unknown>, doc: AuthoringSourceImportData['doc']): boolean {
  return section.doc_id === doc.id && section.tenant_id === doc.tenant_id && typeof section.title === 'string'
    && (typeof section.content === 'string' || section.content === null)
    && Number.isSafeInteger(section.order_index) && Number(section.order_index) >= 0 && Number(section.order_index) <= 2147483647;
}
function validSavedCopy(data: AuthoringSourceImportData | undefined, programId: string): data is AuthoringSourceImportData {
  const doc = data?.doc;
  if (!doc || !importUuid(doc.id) || !nonempty(doc.title) || doc.client_program_id !== programId || !importInteger(doc.tenant_id)) return false;
  return !!data && typeof data.reused === 'boolean' && stringList(data.warnings) && Array.isArray(data.sections) && (data.reused || data.sections.length > 0)
    && validSavedSectionKeys(data.sections) && data.sections.every(section => actualSavedSection(section, doc));
}
function savedSectionsMatch(data: AuthoringSourceImportData, preview: AuthoringSourceImportPreviewData): boolean {
  const codes = new Set(preview.sections.map(s => s.code.trim().toUpperCase()));
  return data.sections.length === codes.size && data.sections.every(section => codes.has(String(section.code).trim().toUpperCase()));
}
const originFields = ['kind', 'id', 'programId', 'title', 'documentType', 'sectionCode', 'conversion'];
const workflowOriginFields = [...originFields, 'fingerprint', 'selection', 'gaps', 'version', 'sourceScope', 'association', 'sectionOrigins'];
const binaryOriginFields = [...originFields, 'fileName', 'mimeType', 'sha256'];
function sameRecordedOrigin(stored: AuthoringImportOrigin, returned: AuthoringImportOrigin, fields: string[]): boolean {
  const project = (origin: AuthoringImportOrigin) => Object.fromEntries(fields.map(key => [key, (origin as unknown as Record<string, unknown>)[key]]));
  return stableStringify(project(stored)) === stableStringify(project(returned));
}
function recordedWorkflowMatches(data: AuthoringSourceImportData, programId: string, source: WorkflowImportSource): boolean {
  const provenance = record(data.doc.provenance);
  const stored = provenance?.importSource as WorkflowImportOrigin | undefined;
  return provenance?.source === 'import' && !!stored && workflowOriginMatches(stored, programId, source)
    && sameRecordedOrigin(stored, data.origin, workflowOriginFields);
}

/** Reused copies keep their actual edited sections. Source hashes describe the
 * imported source version, not the editor's subsequently transformed HTML. */
export function readWorkflowImportResult(body: unknown, programId: string, source: WorkflowImportSource, preview: AuthoringSourceImportPreviewData): AuthoringSourceImportData | null {
  const envelope = body as { success?: boolean; data?: AuthoringSourceImportData } | null;
  const data = envelope?.data;
  if (envelope?.success !== true || !validSavedCopy(data, programId) || !isWorkflowSource(data.origin)) return null;
  if (!readWorkflowPreview({ success: true, data: preview }, programId, source) || !workflowOriginMatches(data.origin as WorkflowImportOrigin, programId, source)) return null;
  if ((data.origin as WorkflowImportOrigin).fingerprint !== preview.fingerprint || !recordedWorkflowMatches(data, programId, source)) return null;
  return data.reused || savedSectionsMatch(data, preview) ? data : null;
}
function binaryOriginMatches(origin: unknown, programId: string, source: BinaryImportSource): origin is BinaryImportOrigin {
  const row = record(origin);
  if (!row || !importUuid(programId) || !validBinarySource(source) || row.kind !== source.kind || row.programId !== programId) return false;
  const id = source.kind === 'vault' ? source.documentId : String(source.sourceId);
  return row.id === id && nonempty(row.title) && nonempty(row.fileName) && nonempty(row.mimeType) && importHash(row.sha256)
    && nullableText(row.documentType) && nullableText(row.sectionCode) && ['docx-structure', 'extracted-text'].includes(String(row.conversion));
}
/** Binary receipts require the saved rows and recorded source version too. */
export function readSourceImportResult(body: unknown, programId: string, source: AuthoringImportSource): SourceImportResult | null {
  const envelope = body as { success?: boolean; data?: AuthoringSourceImportData } | null;
  const data = envelope?.data;
  if (!validBinarySource(source) || envelope?.success !== true || !validSavedCopy(data, programId) || !binaryOriginMatches(data.origin, programId, source)) return null;
  const provenance = record(data.doc.provenance);
  const stored = provenance?.importSource;
  return provenance?.source === 'import' && binaryOriginMatches(stored, programId, source)
    && sameRecordedOrigin(stored, data.origin, binaryOriginFields) ? data : null;
}

const intakeStale = (): SourceIntakeFailure => ({ ok: false, phase: 'stale', message: 'The source, project or signed-in account changed. Reopen this source in its original project before continuing.' });
const intakeRefused = (message: string): SourceIntakeFailure => ({ ok: false, phase: 'refused', message });
const intakeUnknown = (): SourceIntakeFailure => ({ ok: false, phase: 'unknown', message: 'The working-copy save could not be confirmed. Check working documents in the original project before creating another copy.' });
function intakeCurrent(request: SourceIntakeRequest): boolean {
  try { return request.current(); } catch { return false; }
}
function pinIntakeRequest(request: SourceIntakeRequest): SourceIntakeRequest | null {
  if (!intakeCurrent(request) || !importInteger(request.actor.userId) || !importInteger(request.actor.organizationId)) return null;
  if (!nonempty(request.headers.Authorization) || request.headers['x-organization-id'] !== String(request.actor.organizationId)) return null;
  return { actor: { ...request.actor }, headers: { ...request.headers }, current: request.current };
}
function capturedCopy(data: SourceImportResult, request: SourceIntakeRequest): boolean {
  const creator = data.doc.created_by;
  return data.doc.tenant_id === request.actor.organizationId && (typeof creator === 'string' || typeof creator === 'number')
    && String(creator) === String(request.actor.userId);
}
function typedIntakeOutcome(body: unknown, programId: string, request: SourceIntakeRequest): SourceIntakeFailure {
  const recovery = readAuthoringCreationRecovery(body, request.actor.organizationId, programId);
  return { ...intakeUnknown(), identifiedOutcome: true, ...(recovery ? { recovery } : {}) };
}
function failedIntakeResponse(body: unknown, status: number, create: boolean, programId: string, request: SourceIntakeRequest): SourceIntakeFailure {
  if (create && hasAuthoringCreationOutcome(body)) return typedIntakeOutcome(body, programId, request);
  if (create && (status === 408 || status >= 500 || status < 400)) return intakeUnknown();
  return intakeRefused(serverMessage(body) ?? 'The source and target could not be verified. Check access and reload the source preview before retrying.');
}
function failedIntakeError(error: unknown, create: boolean, programId: string, request: SourceIntakeRequest): SourceIntakeFailure {
  if (!intakeCurrent(request)) return intakeStale();
  if (create && error instanceof ApiRequestError && hasAuthoringCreationOutcome({ code: error.code })) return typedIntakeOutcome(error.payload, programId, request);
  return error instanceof ApiRequestError ? failedIntakeResponse(error.payload, error.status, create, programId, request)
    : create ? intakeUnknown() : intakeRefused('The saved source could not be read. Check access and reload its preview.');
}
async function requestSourceIntake<T>(programId: string, payload: Record<string, unknown>, request: SourceIntakeRequest,
  create: boolean, read: (body: unknown) => T | null): Promise<SourceIntakeReply<T>> {
  if (!intakeCurrent(request)) return intakeStale();
  try {
    const response = await apiRequest('POST', '/api/authoring/import/source', payload, request.headers);
    if (!intakeCurrent(request)) return intakeStale();
    const body: unknown = await response.json().catch(() => null);
    if (!intakeCurrent(request)) return intakeStale();
    if (!response.ok || (create && hasAuthoringCreationOutcome(body))) return failedIntakeResponse(body, response.status, create, programId, request);
    const data = read(body);
    return data ? { ok: true, data } : failedIntakeResponse(body, response.status, create, programId, request);
  } catch (error) { return failedIntakeError(error, create, programId, request); }
}
function pinSource<T extends AuthoringImportSource>(source: T): T {
  return { ...source, ...(source.kind === 'csr' && source.sectionNumbers ? { sectionNumbers: [...source.sectionNumbers] } : {}) };
}
function pinPreview(preview: AuthoringSourceImportPreviewData): AuthoringSourceImportPreviewData {
  return JSON.parse(JSON.stringify(preview)) as AuthoringSourceImportPreviewData;
}
export function previewWorkflowImport(programId: string, source: WorkflowImportSource, request: SourceIntakeRequest): Promise<SourceIntakeReply<AuthoringSourceImportPreviewData>> {
  const pinned = pinIntakeRequest(request);
  if (!pinned) return Promise.resolve(intakeStale());
  const selected = pinSource(source);
  if (!importUuid(programId) || !validWorkflowSource(selected)) return Promise.resolve(intakeRefused('Choose a saved source and an existing project.'));
  return requestSourceIntake(programId, { programId, source: selected, previewOnly: true }, pinned, false, body => readWorkflowPreview(body, programId, selected));
}
export function createWorkflowImport(programId: string, source: WorkflowImportSource, preview: AuthoringSourceImportPreviewData, reason: string,
  options: { request: SourceIntakeRequest; associationReason?: string }): Promise<SourceIntakeReply<SourceImportResult>> {
  const request = pinIntakeRequest(options.request);
  if (!request) return Promise.resolve(intakeStale());
  const selected = pinSource(source);
  if (!readWorkflowPreview({ success: true, data: preview }, programId, selected)) return Promise.resolve(intakeRefused('Reload the saved source preview before creating a working copy.'));
  const expected = pinPreview(preview);
  return requestSourceIntake(programId, { programId, source: selected, expectedFingerprint: expected.fingerprint, reason,
    ...(options.associationReason ? { associationReason: options.associationReason } : {}) }, request, true, body => {
    const data = readWorkflowImportResult(body, programId, selected, expected);
    return data && capturedCopy(data, request) ? data : null;
  });
}
export function createBinaryImport(programId: string, source: AuthoringImportSource, reason: string, request: SourceIntakeRequest): Promise<SourceIntakeReply<SourceImportResult>> {
  const pinned = pinIntakeRequest(request);
  if (!pinned) return Promise.resolve(intakeStale());
  const selected = pinSource(source);
  if (!importUuid(programId) || !validBinarySource(selected)) return Promise.resolve(intakeRefused('Choose a saved source and an existing project.'));
  return requestSourceIntake(programId, { programId, source: selected, reason }, pinned, true, body => {
    const data = readSourceImportResult(body, programId, selected);
    return data && capturedCopy(data, pinned) ? data : null;
  });
}

type IntakeInventoryRow = { id: string; title: string; readScope: 'document' | 'sections' };
function readIntakeInventory(body: unknown, programId: string): IntakeInventoryRow[] | null {
  const envelope = record(body);
  if (envelope?.success !== true || !Array.isArray(envelope.documents)) return null;
  const rows = envelope.documents as Array<Record<string, unknown>>;
  if (!rows.every(row => !!row && importUuid(row.id) && nonempty(row.title) && row.program_id === programId
    && (row.readScope === 'document' || row.readScope === 'sections'))) return null;
  if (new Set(rows.map(row => String(row.id).toLowerCase())).size !== rows.length) return null;
  return rows.map(row => ({ id: String(row.id), title: String(row.title), readScope: row.readScope as IntakeInventoryRow['readScope'] }));
}
async function readIntakePath(path: string, request: SourceIntakeRequest): Promise<SourceIntakeReply<unknown>> {
  if (!intakeCurrent(request)) return intakeStale();
  try {
    const response = await apiRequest('GET', path, undefined, request.headers);
    if (!intakeCurrent(request)) return intakeStale();
    const body: unknown = await response.json().catch(() => null);
    if (!intakeCurrent(request)) return intakeStale();
    return response.ok ? { ok: true, data: body } : intakeRefused('The working documents could not be read. Check access in the original project and try the check again.');
  } catch { return intakeCurrent(request) ? intakeRefused('The working documents could not be read. Try the check again in the original project.') : intakeStale(); }
}
function exactIntakeRecovery(attempt: SourceImportInspectionAttempt, request: SourceIntakeRequest, programId: string): AuthoringCreationRecoveryIdentity | null {
  const recovery = attempt.recovery;
  return recovery && importUuid(recovery.documentId) && recovery.organizationId === request.actor.organizationId && recovery.programId === programId
    && (recovery.creationOutcome === 'unconfirmed' || recovery.creationOutcome === 'committed') ? { ...recovery } : null;
}
function recoveredImportBody(detail: unknown, sections: unknown, recovery: AuthoringCreationRecoveryIdentity): unknown {
  const header = record(detail);
  const doc = record(header?.document);
  const rows = record(sections);
  if (header?.success !== true || doc?.id !== recovery.documentId || doc.readScope !== 'document' || doc.sourceMetadataState !== 'available'
    || rows?.success !== true || rows.readScope !== 'document') return null;
  const origin = record(record(doc.provenance)?.importSource);
  return { success: true, data: { doc, sections: rows.sections, origin, warnings: origin?.warnings, reused: true } };
}
function readRecoveredCopy(body: unknown, programId: string, source: AuthoringImportSource, preview: AuthoringSourceImportPreviewData | undefined): SourceImportResult | null {
  return isWorkflowSource(source) ? preview ? readWorkflowImportResult(body, programId, source, preview) : null
    : readSourceImportResult(body, programId, source);
}
async function inspectIdentifiedImport(target: { programId: string; source: AuthoringImportSource; preview?: AuthoringSourceImportPreviewData },
  recovery: AuthoringCreationRecoveryIdentity, request: SourceIntakeRequest, rows: IntakeInventoryRow[]): Promise<SourceIntakeReply<SourceImportResult>> {
  const { programId, source, preview } = target;
  if (!rows.some(row => row.id === recovery.documentId && row.readScope === 'document')) return intakeRefused('The identified document is not currently available as a whole document in this project.');
  const detail = await readIntakePath(authoringCurrentReadPath(recovery.documentId, programId), request);
  if (!detail.ok) return detail;
  const sections = await readIntakePath(authoringCurrentReadPath(recovery.documentId, programId, true), request);
  if (!sections.ok) return sections;
  const data = readRecoveredCopy(recoveredImportBody(detail.data, sections.data, recovery), programId, source, preview);
  return data && capturedCopy(data, request) ? { ok: true, data } : intakeRefused('The identified working copy and its recorded source could not be verified. No document was opened.');
}
/** Read-only inspection never infers a receipt from an inventory title or order. */
export async function inspectSourceImport(programId: string, source: AuthoringImportSource, attempt: SourceImportInspectionAttempt,
  request: SourceIntakeRequest): Promise<SourceImportInspection> {
  const pinned = pinIntakeRequest(request);
  if (!pinned) return intakeStale();
  const selected = pinSource(source);
  if (!importUuid(programId) || !(validWorkflowSource(selected) || validBinarySource(selected))) return intakeRefused('Choose the original saved source and project.');
  const recovery = exactIntakeRecovery(attempt, pinned, programId);
  if ((attempt.identifiedOutcome || attempt.recovery) && !recovery) return { ...intakeUnknown(), identifiedOutcome: true };
  const preview = attempt.preview ? pinPreview(attempt.preview) : undefined;
  const reply = await readIntakePath(`/api/authoring/docs?status=all&programId=${encodeURIComponent(programId)}`, pinned);
  if (!reply.ok) return reply;
  const rows = readIntakeInventory(reply.data, programId);
  if (!rows) return intakeRefused('The working-document inventory could not be verified in the original project. Try the check again.');
  const inventory = rows.map(({ id, title }) => ({ id, title }));
  if (!recovery) return { ok: true, inventory };
  const recovered = await inspectIdentifiedImport({ programId, source: selected, preview }, recovery, pinned, rows);
  if (!recovered.ok) return recovered;
  return { ok: true, inventory, data: recovered.data };
}

/** Exact visible agency question/answer → the existing independent Authoring copy.
 * No agency record, approval or signature is written or adopted here. */
import { createHash } from 'node:crypto';
import { stableStringify } from '../../../shared/canonical-json';
import { plainTextToHtml } from '../../../shared/authoring/plain-text-html';
import { agencyResponseImportId, type WorkflowImportOrigin, type WorkflowImportSource } from '../../../shared/authoring/source-import';
import { readLetter } from '../agency-responses/response-service';
import { canViewVisibilityTier } from '../agency-responses/visibility';
import { readCsrProjectActor } from '../csr/project-scope';
import { programInOrganization } from '../c2c/program-access';
import { readProgramAnchorRow } from '../c2c/program-project-anchor';
import { canAccessReportProject } from '../report-os/project-access';
import type { Queryable } from './authoring-evidence';
import { WorkflowSourceImportError, type MaterializedWorkflowSource, type WorkflowMaterializationInput } from './workflow-source-import';

export const AGENCY_CONTEXT_SECTION_CODE = 'agency.context';
export const AGENCY_RESPONSE_SECTION_CODE = 'agency.response';
type AgencySource = Extract<WorkflowImportSource, { kind: 'agency-response' }>;
type AgencyInput = WorkflowMaterializationInput & { source: AgencySource };
const sha = (value: string) => createHash('sha256').update(value, 'utf8').digest('hex');
const fail = (status: WorkflowSourceImportError['status'], code: string, message: string): never => {
  throw new WorkflowSourceImportError(status, code, message);
};
const warnings = [
  'This is an independent working draft. Source completion, approval and signatures are not transferred.',
  'Save and review the response in the editor, then explicitly record that saved response on the original agency question. Editing this copy alone does not update the response register or package.',
  'Original authorship, model use, source support and scientific or regulatory correctness are not established by this copy or its fingerprint.',
];

async function admittedSource(input: AgencyInput, q: Queryable) {
  const actor = await readCsrProjectActor(q, input.organizationId, input.userId);
  const programId = input.target.programId.toLowerCase();
  if (!await programInOrganization(q, programId, input.organizationId)) return fail(404, 'AGENCY_SOURCE_NOT_FOUND', 'Agency response source not found in this project.');
  const anchor = await readProgramAnchorRow(q, { programId, orgId: input.organizationId, context: 'agency-response-workflow-import', requireUnique: true });
  if (!anchor || anchor.id !== input.target.projectId) return fail(409, 'AGENCY_SOURCE_SCOPE_MISMATCH', 'The agency response target project could not be verified.');
  if (!await canAccessReportProject(input.organizationId, actor, anchor.id, q)) return fail(403, 'AGENCY_SOURCE_ACCESS_DENIED', 'Current project access is required to read this agency response.');
  const letter = await readLetter(q, input.organizationId, anchor.id, input.source.eventId);
  if (!letter || !canViewVisibilityTier(letter.visibilityTier as Parameters<typeof canViewVisibilityTier>[0], actor.role)) {
    return fail(404, 'AGENCY_SOURCE_NOT_FOUND', 'Agency response source not found in this project.');
  }
  if (letter.closureStatus === 'closed') return fail(409, 'AGENCY_SOURCE_CLOSED', 'This agency letter is closed. Its response cannot start a new editing copy.');
  const response = await q.query(`SELECT id, organization_id, project_id, communication_event_id,
      question_ref, question_text, discipline, ctd_section, response_text, response_revision, withdrawn_at
    FROM agency_communication_questions
    WHERE id=$1 AND organization_id=$2 AND project_id=$3 AND communication_event_id=$4`,
  [input.source.questionId, input.organizationId, anchor.id, input.source.eventId]);
  if (response.rows.length !== 1) return fail(404, 'AGENCY_SOURCE_NOT_FOUND', 'Agency response source not found in this project.');
  const row: Record<string, unknown> = response.rows[0];
  if (row.withdrawn_at != null) return fail(409, 'AGENCY_SOURCE_WITHDRAWN', 'This agency question is withdrawn. Its response cannot start a new editing copy.');
  if (row.id !== input.source.questionId || row.organization_id !== input.organizationId || row.project_id !== anchor.id
    || row.communication_event_id !== input.source.eventId || typeof row.question_ref !== 'string' || !row.question_ref.trim()
    || row.question_ref.length > 40 || typeof row.question_text !== 'string' || !row.question_text.trim() || row.question_text.length > 20_000
    || typeof row.response_text !== 'string' || row.response_text.length > 100_000
    || typeof row.response_revision !== 'number' || !Number.isSafeInteger(row.response_revision) || row.response_revision < 0 || row.response_revision > 2_147_483_647
    || (row.discipline != null && typeof row.discipline !== 'string') || (row.ctd_section != null && typeof row.ctd_section !== 'string')) {
    return fail(409, 'AGENCY_SOURCE_INVALID', 'The recorded agency question or response version is invalid.');
  }
  return { letter, row: { id: row.id, questionRef: row.question_ref, questionText: row.question_text,
    discipline: row.discipline ?? null, ctdSection: row.ctd_section ?? null,
    responseText: row.response_text, responseRevision: row.response_revision },
  scope: { level: 'program' as const, programId, projectId: anchor.id } };
}

export async function materializeAgencyResponseSource(input: AgencyInput, q: Queryable): Promise<MaterializedWorkflowSource> {
  const id = agencyResponseImportId(input.source.eventId, input.source.questionId);
  if (!id) return fail(400, 'WORKFLOW_SOURCE_INVALID', 'Choose an exact saved agency question.');
  const { letter, row, scope } = await admittedSource(input, q);
  const source: AgencySource = { kind: 'agency-response', eventId: input.source.eventId, questionId: input.source.questionId };
  const title = `Agency response ${row.questionRef} — ${letter.communicationType}`;
  const sections = [
    { code: AGENCY_CONTEXT_SECTION_CODE, title: 'Recorded agency question and working-copy limits', content: plainTextToHtml([
      `Letter: ${letter.communicationType}`, `Recorded event: ${letter.eventId}`, `Question: ${row.questionRef}`,
      row.questionText, `Discipline: ${row.discipline ?? 'not recorded'}`, `Recorded CTD section: ${row.ctdSection ?? 'not recorded'}`,
      `Response revision: ${row.responseRevision}`, ...warnings,
    ].join('\n\n')) },
    { code: AGENCY_RESPONSE_SECTION_CODE, title: `Response to ${row.questionRef}`, content: plainTextToHtml(row.responseText) },
  ];
  const gaps = row.responseText.trim() ? [] : ['This question has no saved response. Prepare source-supported response text before recording it on the agency question.'];
  const sectionOrigins = sections.map(section => ({ code: section.code, sourceRowId: `agency_communication_questions:${row.id}`,
    contentSha256: sha(section.content), originalAuthorship: 'unknown' as const, model: null, modelEvidence: 'unrecorded' as const }));
  const fingerprint = sha(stableStringify({ source, scope, letter: { eventId: letter.eventId, communicationType: letter.communicationType,
    sourceType: letter.sourceType, visibilityTier: letter.visibilityTier, closureStatus: letter.closureStatus, responseRequired: letter.responseRequired },
  question: row, sections, sectionOrigins, gaps }));
  const origin: WorkflowImportOrigin = { kind: source.kind, id, title, programId: scope.programId,
    documentType: null, sectionCode: null, fingerprint, selection: source, gaps, version: String(row.responseRevision),
    conversion: 'agency-response-snapshot', sourceScope: scope, association: { mode: 'recorded', reason: null }, sectionOrigins };
  return { origin, fingerprint, sections, gaps, warnings: [...warnings], association: { mode: 'recorded', required: false,
    reasonRequired: false, sourceProgramId: scope.programId, sourceProjectId: scope.projectId, targetProgramId: scope.programId } };
}

/** A working copy keeps its exact original dependency through later exports.
 * Keeping extracted data permits renditions; withdrawing data does not. */
import { agencyResponseImportId, isWorkflowImportOrigin, studyDesignImportId, type AuthoringImportOrigin, type WorkflowImportOrigin } from '../../../shared/authoring/source-import';
import { isDeepStrictEqual } from 'node:util';
import { authorizeAuthoringProgram } from './authoring-program-access';
import type { AuthoringActor } from './authoring-documents';
import { materializeWorkflowSource, type MaterializedWorkflowSource } from './workflow-source-import';
import { capturedDataEligibleSql, vaultDataEligibleSql } from '../document-data-disposition/eligibility';
import { programInOrganization } from '../c2c/program-access';
import type { Queryable } from './authoring-evidence';

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const HASH = /^[0-9a-f]{64}$/i;

function workflowIdentityMatches(source: WorkflowImportOrigin): boolean {
  if (source.kind === 'agency-response') return typeof source.id === 'string' && source.selection?.kind === 'agency-response'
    && agencyResponseImportId(source.selection.eventId, source.selection.questionId) !== null
    && agencyResponseImportId(source.selection.eventId, source.selection.questionId) === source.id;
  const ivd = source.kind === 'ivd-assessment' || source.kind === 'ivd-document';
  const study = source.kind === 'study-design-crf';
  const idValid = study ? typeof source.id === 'string' && studyDesignImportId(source.id) === source.id : ivd ? UUID.test(source.id) : /^[1-9]\d*$/.test(source.id);
  const selectionId = source.selection?.kind === 'agency-response' ? agencyResponseImportId(source.selection.eventId, source.selection.questionId)
    : source.selection?.kind === 'study-design-crf' ? source.selection.studyId
    : source.selection?.kind === 'csr' ? source.selection.jobId : source.selection?.documentId;
  return idValid && source.selection?.kind === source.kind && String(selectionId) === source.id;
}

function hasWorkflowIdentity(source: WorkflowImportOrigin): boolean {
  return workflowIdentityMatches(source) && HASH.test(source.fingerprint)
    && Array.isArray(source.sectionOrigins) && source.sectionOrigins.length > 0
    && source.sectionOrigins.every(s => typeof s.code === 'string' && HASH.test(s.contentSha256) && ['machine', 'template', 'unknown'].includes(s.originalAuthorship))
    && Array.isArray(source.gaps) && source.gaps.every(g => typeof g === 'string');
}

function hasVerifiedImportIdentity(source: AuthoringImportOrigin): boolean {
  if (isWorkflowImportOrigin(source)) return hasWorkflowIdentity(source);
  if (typeof source.id !== 'string' || typeof source.sha256 !== 'string' || !HASH.test(source.sha256)) return false;
  if (source.kind === 'vault') return UUID.test(source.id);
  return source.kind === 'data-room' && /^[1-9]\d*$/.test(source.id);
}

function importMatchesProject(source: AuthoringImportOrigin, programId: unknown): boolean {
  return typeof programId === 'string' && UUID.test(programId) && typeof source.programId === 'string'
    && source.programId.toLowerCase() === programId.toLowerCase();
}

export function savedImportSource(doc: { provenance?: unknown; client_program_id?: unknown }): AuthoringImportOrigin | null {
  const provenance = doc.provenance;
  if (!provenance || typeof provenance !== 'object' || Array.isArray(provenance)) return null;
  const value = (provenance as Record<string, unknown>).importSource;
  if (value === undefined) return null;
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Invalid saved import origin');
  const source = value as AuthoringImportOrigin;
  if (!importMatchesProject(source, doc.client_program_id) || !hasVerifiedImportIdentity(source)) {
    throw new Error('Invalid saved import identity or version');
  }
  return source;
}

export async function verifySavedImportSource(doc: { provenance?: unknown; client_program_id?: unknown }, q: Queryable, organizationId: number, actor?: AuthoringActor): Promise<void> {
  const source = savedImportSource(doc);
  if (!source) return;
  if (isWorkflowImportOrigin(source)) {
    if (!actor) throw new Error('Current workflow source actor required');
    await verifySavedWorkflowImport(doc, q, { organizationId, actor });
    return;
  }
  // A retained document grant does not grant perpetual access to its private
  // project sources. Interactive consumers supply their verified current actor.
  if (actor) await authorizeAuthoringProgram(q, { tenantId: organizationId, actor, programId: source.programId, forWrite: false });
  else if (!(await programInOrganization(q, source.programId, organizationId))) throw new Error('Imported source project unavailable');
  const result = source.kind === 'vault'
    ? await q.query(`SELECT d.content_hash AS hash FROM vault.documents d
        WHERE d.id=$1 AND d.program_id=$2 AND d.deleted_at IS NULL
          AND to_jsonb(d)->>'organization_id'=$3::text AND ${vaultDataEligibleSql('d')} FOR SHARE OF d`,
      [source.id, source.programId, organizationId])
    : await q.query(`SELECT s.checksum AS hash FROM cre_evidence_sources s
        WHERE s.id=$1 AND s.client_program_id=$2 AND s.organization_id=$3
          AND s.source_type='client_document' AND s.is_current IS NOT FALSE AND s.deleted_at IS NULL
          AND ${capturedDataEligibleSql('s')} FOR SHARE OF s`, [source.id, source.programId, organizationId]);
  if (result.rows.length !== 1 || String(result.rows[0].hash ?? '').trim().toLowerCase() !== source.sha256.toLowerCase()) {
    throw new Error('Imported source unavailable or changed');
  }
}

/** Current source/target access and snapshot verification for governance callers.
 * The receipt does not confer perpetual project access or scientific qualification. */
export async function verifySavedWorkflowImport(doc: { provenance?: unknown; client_program_id?: unknown }, q: Queryable,
  input: { organizationId: number; actor: AuthoringActor }): Promise<MaterializedWorkflowSource | null> {
  const origin = savedImportSource(doc);
  if (!origin || !isWorkflowImportOrigin(origin)) return null;
  const target = await authorizeAuthoringProgram(q, { tenantId: input.organizationId, actor: input.actor, programId: origin.programId, forWrite: false });
  const current = await materializeWorkflowSource({ organizationId: input.organizationId, userId: Number(input.actor.id),
    target: { programId: origin.programId, projectId: target.projectId }, source: origin.selection,
    ...(origin.association.reason ? { associationReason: origin.association.reason } : {}) }, q);
  if (current.fingerprint !== origin.fingerprint) throw new Error('Imported workflow source changed or unavailable');
  if (!isDeepStrictEqual(current.origin.sectionOrigins, origin.sectionOrigins)
    || !isDeepStrictEqual(current.origin.sourceScope, origin.sourceScope)) throw new Error('Stored workflow origin annotations do not match the verified source');
  return current;
}

/** Read exact stored workflow content on the caller's snapshot. This module
 * writes no document, reservation, source association or approval evidence. */
import { createHash } from 'node:crypto';
import { createScopedLogger } from '../../utils/logger';
const sourceLogger = createScopedLogger('workflow-source-import');
import { stableStringify } from '../../../shared/canonical-json';
import type { WorkflowImportSource, WorkflowImportOrigin, WorkflowImportAssociation, WorkflowSectionOrigin } from '../../../shared/authoring/source-import';
import { agencyResponseImportId, studyDesignImportId } from '../../../shared/authoring/source-import';
import type { Queryable } from './authoring-evidence';
import { requireCsrJobAccess, readCsrProjectActor, CsrScopeError } from '../csr/project-scope';
import { canAccessReportProject } from '../report-os/project-access';
import { readProgramAnchorRow } from '../c2c/program-project-anchor';
import { ICH_E3_STRUCTURE, flattenICHE3Sections } from '../csr-builder';
import { loadProtocolExportSnapshot, type ProtocolCompositionSnapshot } from '../protocol-export/protocol-export-service';
import { protocolAuthoringSections } from '../protocol-export/protocol-export-logic';
import { validateSoa } from '../protocol-soa/protocol-soa-logic';
import { listLiveMachineSpans, hashSpanText } from '../clinical-regulatory-evidence/span-lineage.service';
import { WORKFLOW_IMPORT_AUTHOR_ID } from './revision-ledger';
import { verifyRetainedProtocolMatrixEndpoints } from './protocol-import-matrix';

export class WorkflowSourceImportError extends Error {
  constructor(readonly status: 400 | 403 | 404 | 409 | 503, readonly code: string, message: string) {
    super(message); this.name = 'WorkflowSourceImportError';
  }
}
export interface WorkflowMaterializationInput {
  organizationId: number; userId: number;
  target: { programId: string; projectId: number };
  source: WorkflowImportSource; associationReason?: string;
}
export interface MaterializedWorkflowSource {
  origin: WorkflowImportOrigin; fingerprint: string;
  sections: Array<{code:string;title:string;content:string}>;
  gaps: string[]; warnings: string[]; association: WorkflowImportAssociation;
}
type Scope = WorkflowImportOrigin['sourceScope'];
type Composition = {
  title: string; version: string | null; scope: Scope;
  sections: MaterializedWorkflowSource['sections']; sectionOrigins: WorkflowSectionOrigin[];
  gaps: string[]; facts: unknown;
};
const HASH = /^[0-9a-f]{64}$/;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const sha = (value: string) => createHash('sha256').update(value, 'utf8').digest('hex');
const fail = (status: WorkflowSourceImportError['status'], code: string, message: string): never => { throw new WorkflowSourceImportError(status, code, message); };
const positive = (value: unknown): value is number => typeof value === 'number' && Number.isSafeInteger(value) && value > 0 && value <= 2_147_483_647;

function sourceOrigin(code: string, sourceRowId: string, content: string, authorship: WorkflowSectionOrigin['originalAuthorship'] = 'unknown', model: string | null = null): WorkflowSectionOrigin {
  return { code, sourceRowId, contentSha256: sha(content), originalAuthorship: authorship, model, modelEvidence: model ? 'recorded-name-only' : 'unrecorded' };
}

function validateInput(input: WorkflowMaterializationInput): void {
  if (!positive(input.organizationId) || !positive(input.userId) || !positive(input.target.projectId) || !UUID.test(input.target.programId)) fail(400, 'WORKFLOW_SCOPE_INVALID', 'A verified organization actor and target project are required.');
  if (input.source.kind === 'agency-response') {
    if (!agencyResponseImportId(input.source.eventId, input.source.questionId)) fail(400, 'WORKFLOW_SOURCE_INVALID', 'Choose an exact saved agency question.');
    return;
  }
  if (input.source.kind === 'study-design-crf') {
    const id = input.source.studyId;
    if (typeof id !== 'string' || studyDesignImportId(id) !== id) fail(400, 'WORKFLOW_SOURCE_INVALID', 'Choose an exact saved study design.');
    return;
  }
  const id = input.source.kind === 'csr' ? input.source.jobId : input.source.documentId;
  if (input.source.kind === 'ivd-assessment' || input.source.kind === 'ivd-document') {
    if (typeof id !== 'string' || !UUID.test(id)) fail(400, 'WORKFLOW_SOURCE_INVALID', 'Choose an exact saved IVD record.');
    return;
  }
  if (!positive(id)) fail(400, 'WORKFLOW_SOURCE_INVALID', 'Choose an exact saved protocol or CSR job.');
}

async function protocolRecordedProgram(input: WorkflowMaterializationInput, q: Queryable): Promise<unknown> {
  const { rows } = await q.query("SELECT id, study_design_id, to_jsonb(protocol_documents)->>'program_id' AS program_id FROM protocol_documents WHERE id = $1 AND organization_id = $2 AND deleted_at IS NULL", [input.source.kind === 'protocol' ? input.source.documentId : 0, input.organizationId]);
  if (rows.length !== 1) return fail(404, 'WORKFLOW_SOURCE_NOT_FOUND', 'Saved protocol not found.');
  const stored = rows[0].program_id;
  const studyId = rows[0].study_design_id;
  if (studyId === null) return stored ?? null;
  if (typeof studyId !== 'string' || !studyId.trim()) return fail(409, 'WORKFLOW_SOURCE_SCOPE_UNAVAILABLE', 'The protocol study-design relationship could not be verified.');
  const designs = await q.query('SELECT program_id FROM cdisc_prm_studies WHERE study_id = $1 AND tenant_id = $2', [studyId, input.organizationId]);
  if (designs.rows.length !== 1) return fail(409, 'WORKFLOW_SOURCE_SCOPE_UNAVAILABLE', 'The protocol recorded study design is unavailable for this organization.');
  const designProgram = designs.rows[0].program_id;
  if (stored != null && stored !== designProgram) return fail(409, 'WORKFLOW_SOURCE_SCOPE_MISMATCH', 'The saved protocol and its bound design disagree about their project.');
  return stored ?? designProgram;
}

async function protocolScope(input: WorkflowMaterializationInput, q: Queryable): Promise<Scope> {
  const recorded = await protocolRecordedProgram(input, q);
  const actor = await readCsrProjectActor(q, input.organizationId, input.userId);
  if (recorded === null) return {level:'organization',programId:null,projectId:null};
  if (typeof recorded !== 'string' || !UUID.test(recorded)) return fail(409, 'WORKFLOW_SOURCE_SCOPE_UNAVAILABLE', 'The protocol’s recorded project relationship is invalid.');
  const programId = recorded.toLowerCase();
  const anchor = await readProgramAnchorRow(q, {programId,orgId:input.organizationId,context:'protocol-workflow-import',requireUnique:true});
  if (!anchor || !await canAccessReportProject(input.organizationId, actor, anchor.id, q)) return fail(403, 'WORKFLOW_SOURCE_ACCESS_DENIED', 'The saved protocol project is not accessible to this actor.');
  if (programId !== input.target.programId.toLowerCase() || anchor.id !== input.target.projectId) return fail(409, 'WORKFLOW_SOURCE_SCOPE_MISMATCH', 'This protocol belongs to another recorded project. Choose its recorded project.');
  return {level:'program',programId,projectId:anchor.id};
}

function protocolGaps(snapshot: ProtocolCompositionSnapshot): string[] {
  const { document, sourceRows } = snapshot;
  const gaps: string[] = [];
  if (!document.synopsis?.trim()) gaps.push('The saved protocol has no synopsis.');
  if (!document.objectives.length) gaps.push('The saved protocol has no structured objectives or endpoints.');
  if (!sourceRows.eligibility.length) gaps.push('The saved protocol has no structured eligibility criteria.');
  for (const row of sourceRows.sections) if (row.required === true && (typeof row.content !== 'string' || !row.content.trim())) gaps.push(`Required protocol section ${String(row.section_key)} has no saved content.`);
  if (document.soa) gaps.push(...validateSoa(document.soa.matrix, sourceRows.assessments.map(row => ({id:Number(row.id),name:String(row.name),category:String(row.category)}))).findings.map(f => f.message));
  return gaps;
}

function validateProtocolStructure(snapshot: ProtocolCompositionSnapshot): void {
  const { sourceRows } = snapshot;
  if (typeof sourceRows.document.title !== 'string' || typeof sourceRows.document.version !== 'string') fail(409, 'WORKFLOW_SOURCE_INVALID', 'The saved protocol identification is invalid.');
  for (const rows of [sourceRows.sections, sourceRows.objectives, sourceRows.eligibility, sourceRows.visits, sourceRows.assessments, sourceRows.cells]) {
    if (!rows.every(row => positive(row.id))) fail(409, 'WORKFLOW_SOURCE_INVALID', 'The saved protocol contains an invalid structured row identity.');
  }
  if (!sourceRows.cells.every(row => positive(row.assessment_id) && positive(row.visit_id) && typeof row.required === 'boolean')) fail(409, 'WORKFLOW_SOURCE_INVALID', 'The saved assessment matrix contains an invalid endpoint identity.');
}

async function composeProtocol(input: WorkflowMaterializationInput, q: Queryable): Promise<Composition> {
  const scope = await protocolScope(input, q);
  const id = input.source.kind === 'protocol' ? input.source.documentId : 0;
  const snapshot = await loadProtocolExportSnapshot(input.organizationId, id, q, {contentOnly:true});
  validateProtocolStructure(snapshot);
  const retired = await verifyRetainedProtocolMatrixEndpoints(q, input.organizationId, id, snapshot.sourceRows);
  if (!retired) return fail(409, 'WORKFLOW_SOURCE_INVALID', 'The saved assessment matrix contains a cell outside this protocol.');
  const sections = protocolAuthoringSections(snapshot.document);
  const structuredRows: Record<string, string> = {
    'protocol.header':`protocol_documents:${id}`, 'protocol.synopsis':`protocol_documents:${id}`,
    'protocol.objectives':`protocol_objectives:${snapshot.sourceRows.objectives.map(r => r.id).join(',')}`,
    'protocol.eligibility':`protocol_eligibility_criteria:${snapshot.sourceRows.eligibility.map(r => r.id).join(',')}`,
    'protocol.schedule':`protocol_schedule_visits:${snapshot.sourceRows.visits.map(r => r.id).join(',')}`,
    'protocol.soa':`protocol_soa_assessments:${snapshot.sourceRows.assessments.map(r => r.id).join(',')};protocol_soa_cells:${snapshot.sourceRows.cells.map(r => r.id).join(',')};protocol_schedule_visits:${snapshot.sourceRows.visits.map(r => r.id).join(',')}`,
  };
  const machineLineage: Record<string, unknown> = {};
  const sectionOrigins = await Promise.all(sections.map(async section => {
    const row = snapshot.sourceRows.sections.find(r => r.section_key === section.code);
    const sourceRowId = row ? `protocol_sections:${row.id}` : structuredRows[section.code];
    if (!row && section.code !== 'protocol.synopsis') return sourceOrigin(section.code, sourceRowId, section.content);
    const spans = (await listLiveMachineSpans(input.organizationId, {documentTable:row ? 'protocol_sections' : 'protocol_documents',documentId:String(row?.id ?? id)},q))
      .sort((a,b)=>sha(stableStringify(a)).localeCompare(sha(stableStringify(b))));
    if (!spans.every(span => Number.isSafeInteger(span.charStart) && Number.isSafeInteger(span.charEnd)
      && span.charStart >= 0 && span.charEnd > span.charStart && span.charEnd <= section.content.length
      && hashSpanText(section.content.slice(span.charStart,span.charEnd)) === span.spanTextSha256)) return fail(409,'WORKFLOW_SOURCE_LINEAGE_UNVERIFIED','Saved protocol machine lineage does not match the current source text. Reconcile its source provenance before importing.');
    machineLineage[section.code] = spans;
    // The deterministic importer is a copy operation, not proof that a model
    // originated these words. Ordinary assertions/tool transport also supply no
    // machine authorship; actual machine span proof remains unqualified here.
    return sourceOrigin(section.code, sourceRowId, section.content,spans.some(span=>span.machineAuthorId !== WORKFLOW_IMPORT_AUTHOR_ID) ? 'machine' : 'unknown');
  }));
  const retiredFacts = retired.visits.length || retired.assessments.length ? { retiredMatrixEndpoints: retired } : {};
  return {title:snapshot.document.title,version:snapshot.document.header.version,scope,sections,sectionOrigins,gaps:protocolGaps(snapshot),facts:{...snapshot.sourceRows,machineLineage,...retiredFacts}};
}

const CSR_CATALOG = flattenICHE3Sections(ICH_E3_STRUCTURE);
const CSR_CODES = new Map(CSR_CATALOG.map((section, index) => [section.number, {section,index}]));
const selectedBy = (code: string, selections: readonly string[]) => selections.some(parent => code === parent || code.startsWith(`${parent}.`));

function csrSelection(source: Extract<WorkflowImportSource,{kind:'csr'}>): string[] | undefined {
  if (source.sectionNumbers === undefined) return undefined;
  if (!Array.isArray(source.sectionNumbers) || !source.sectionNumbers.length || source.sectionNumbers.length > 200 || !source.sectionNumbers.every(code => typeof code === 'string' && CSR_CODES.has(code))) return fail(400, 'WORKFLOW_CSR_SELECTION_INVALID', 'Choose actual ICH E3 section numbers from this saved CSR.');
  return [...new Set(source.sectionNumbers)].sort((a,b) => CSR_CODES.get(a)!.index - CSR_CODES.get(b)!.index);
}

function csrSections(rows: Record<string, unknown>[], selection: string[] | undefined): Pick<Composition,'sections'|'sectionOrigins'> {
  const selected = rows.filter(row => typeof row.section_number === 'string' && (!selection || selectedBy(row.section_number, selection)));
  if (!selected.length) return fail(409, 'WORKFLOW_CSR_OUTPUT_MISSING', 'No saved output exists for the selected CSR section.');
  for (const code of selection ?? []) if (!selected.some(row => selectedBy(String(row.section_number), [code]))) return fail(409, 'WORKFLOW_CSR_OUTPUT_MISSING', `No saved output exists for selected CSR section ${code}.`);
  selected.sort((a,b) => (CSR_CODES.get(String(a.section_number))?.index ?? -1) - (CSR_CODES.get(String(b.section_number))?.index ?? -1));
  const sections: Composition['sections'] = [];
  const sectionOrigins: WorkflowSectionOrigin[] = [];
  for (const row of selected) {
    const verified = verifiedCsrSection(row);
    sections.push(verified.section);
    sectionOrigins.push(verified.origin);
  }
  return {sections,sectionOrigins};
}

function csrAuthorship(row: Record<string,unknown>): Pick<WorkflowSectionOrigin,'originalAuthorship'|'model'> {
  if (typeof row.ai_generated !== 'boolean' || (row.model != null && typeof row.model !== 'string')) return fail(409, 'WORKFLOW_CSR_ORIGIN_INVALID', 'The selected CSR section origin is invalid.');
  const lineage = row.lineage && typeof row.lineage === 'object' ? row.lineage as Record<string,unknown> : {};
  return {originalAuthorship:row.ai_generated ? 'machine' : lineage.source === 'template' ? 'template' : 'unknown',model:typeof row.model === 'string' && row.model.trim() ? row.model.trim() : null};
}

function verifiedCsrSection(row: Record<string,unknown>) {
  const code = row.section_number;
  const catalog = typeof code === 'string' ? CSR_CODES.get(code) : null;
  if (!positive(row.id) || !catalog || typeof row.content !== 'string' || !row.content.trim()) return fail(409, 'WORKFLOW_CSR_OUTPUT_INVALID', 'The selected CSR contains an invalid or empty saved section.');
  if (typeof row.content_hash !== 'string' || !HASH.test(row.content_hash) || sha(row.content) !== row.content_hash) return fail(409, 'WORKFLOW_CSR_HASH_MISMATCH', `Saved CSR section ${code} does not match its recorded content hash.`);
  const {originalAuthorship,model} = csrAuthorship(row);
  return {section:{code:String(code),title:catalog.section.title,content:row.content},origin:sourceOrigin(String(code),`csr_section_outputs:${row.id}`,row.content,originalAuthorship,model)};
}

type CsrJob = {id:number;project_id:number|null;study_id:string;status:string;sections_to_generate:string[]|null;study_info_snapshot:unknown};
function verifiedCsrJob(row: Record<string,unknown> | undefined, targetProjectId: number): CsrJob {
  if (!row || !positive(row.id) || typeof row.study_id !== 'string' || typeof row.status !== 'string') return fail(409, 'WORKFLOW_SOURCE_INVALID', 'The saved CSR job identification is invalid.');
  if (row.project_id !== null && (!positive(row.project_id) || row.project_id !== targetProjectId)) return fail(409, 'WORKFLOW_SOURCE_SCOPE_MISMATCH', 'The saved CSR belongs to another recorded project.');
  if (row.sections_to_generate !== null && (!Array.isArray(row.sections_to_generate) || !row.sections_to_generate.every(code => typeof code === 'string' && CSR_CODES.has(code)))) return fail(409, 'WORKFLOW_SOURCE_INVALID', 'The saved CSR requested section set is invalid.');
  return {id:row.id,project_id:row.project_id,study_id:row.study_id,status:row.status,sections_to_generate:row.sections_to_generate?.length ? row.sections_to_generate : null,study_info_snapshot:row.study_info_snapshot};
}

function csrGaps(job: CsrJob, sections: Composition['sections'], selection: string[] | undefined): string[] {
  const present = new Set(sections.map(s=>s.code));
  const expected = selection ? CSR_CATALOG.filter(s => selectedBy(s.number,selection)).map(s=>s.number) : job.sections_to_generate ?? CSR_CATALOG.map(s=>s.number);
  const gaps = expected.filter(code=>!present.has(code)).map(code=>`CSR section ${code} has no saved output in this selection.`);
  if (job.status !== 'complete') gaps.unshift(`The saved CSR job is ${job.status}; available output is a partial draft.`);
  for (const section of sections) if (/\[DATA TO BE INSERTED\]/i.test(section.content)) gaps.push(`CSR section ${section.code} retains a data-to-be-inserted placeholder.`);
  return gaps;
}

function csrTitle(job: CsrJob): string {
  const snapshot = job.study_info_snapshot && typeof job.study_info_snapshot === 'object' ? job.study_info_snapshot as Record<string,unknown> : {};
  const study = snapshot.studyInfo && typeof snapshot.studyInfo === 'object' ? snapshot.studyInfo as Record<string,unknown> : snapshot;
  return typeof study.title === 'string' && study.title.trim() ? study.title : `Clinical study report for ${job.study_id}`;
}

async function composeCsr(input: WorkflowMaterializationInput & { source: Extract<WorkflowImportSource, {kind:'csr'}> }, q: Queryable): Promise<Composition> {
  if (input.source.kind !== 'csr') return fail(400, 'WORKFLOW_SOURCE_INVALID', 'Choose an exact CSR job.');
  const selection = csrSelection(input.source);
  if (!await requireCsrJobAccess(q, input.organizationId, input.source.jobId, input.userId)) return fail(404, 'WORKFLOW_SOURCE_NOT_FOUND', 'Saved CSR job not found.');
  const jobResult = await q.query('SELECT id, project_id, study_id, status, sections_to_generate, study_info_snapshot FROM csr_build_jobs WHERE id = $1 AND organization_id = $2', [input.source.jobId,input.organizationId]);
  const job = verifiedCsrJob(jobResult.rows[0],input.target.projectId);
  // Scope identity is checked without selecting prose from a mismatched output.
  const identities = await q.query('SELECT id, project_id FROM csr_section_outputs WHERE job_id = $1 AND organization_id = $2', [input.source.jobId,input.organizationId]);
  if (!identities.rows.every((row: Record<string,unknown>) => row.project_id === job.project_id)) return fail(409, 'WORKFLOW_SOURCE_SCOPE_MISMATCH', 'Saved CSR output does not match its job project scope.');
  const output = await q.query(`SELECT id, section_number, content, content_hash, ai_generated, model, lineage, generated_at
    FROM csr_section_outputs WHERE job_id = $1 AND organization_id = $2 AND project_id IS NOT DISTINCT FROM $3 ORDER BY section_number, id`, [input.source.jobId,input.organizationId,job.project_id]);
  const composed = csrSections(output.rows, selection);
  const present = new Set(composed.sections.map(s => s.code));
  const gaps = csrGaps(job,composed.sections,selection);
  const title = csrTitle(job);
  const scope: Scope = job.project_id == null ? {level:'organization',programId:null,projectId:null} : {level:'project',programId:null,projectId:job.project_id};
  const selectedOutputs = output.rows.filter((row: Record<string,unknown>) => present.has(String(row.section_number)));
  return {...composed,title,version:null,scope,gaps,facts:{job,outputs:selectedOutputs,selection:selection ?? null}};
}

function finish(input: WorkflowMaterializationInput & { source: Extract<WorkflowImportSource, {kind:'csr'|'protocol'}> }, composition: Composition): MaterializedWorkflowSource {
  const {sections,sectionOrigins,gaps,scope} = composition;
  if (sections.length > 200 || sections.reduce((n,s) => n + s.content.length,0) > 2_000_000 || new Set(sections.map(s => s.code)).size !== sections.length) return fail(409, 'WORKFLOW_SOURCE_LIMIT', 'The saved workflow is too large or has ambiguous section keys for one authoring draft.');
  const mode = scope.level === 'organization' ? 'explicit' : 'recorded';
  const association: WorkflowImportAssociation = {mode,required:mode === 'explicit',reasonRequired:mode === 'explicit',sourceProgramId:scope.programId,sourceProjectId:scope.projectId,targetProgramId:input.target.programId};
  const source: WorkflowImportSource = input.source.kind === 'csr'
    ? {kind:'csr',jobId:input.source.jobId,...(input.source.sectionNumbers ? {sectionNumbers:csrSelection(input.source)} : {})} : {kind:'protocol',documentId:input.source.documentId};
  const fingerprint = sha(stableStringify({source,scope,mode,facts:composition.facts,sectionOrigins,sections,gaps}));
  const origin: WorkflowImportOrigin = {
    kind:input.source.kind,id:String(input.source.kind === 'csr' ? input.source.jobId : input.source.documentId),programId:input.target.programId,
    title:composition.title,documentType:null,sectionCode:null,fingerprint,version:composition.version,
    conversion:input.source.kind === 'csr' ? 'ich-e3-sections' : 'protocol-structure',sourceScope:scope,
    association:{mode,reason:mode === 'explicit' ? input.associationReason?.trim() || null : null},sectionOrigins,
    selection:source,gaps,
  };
  const warnings = ['This is an unbound working draft. Source completion, approval and signatures are not transferred.',
    'Original authorship and model qualification are not established by a workflow fingerprint.',
    'Verified generation document/hash/span support was not recorded by this materializer.'];
  if (mode === 'explicit') warnings.push('The source has no recorded project association. Creation requires an explicit association reason.');
  return {origin,fingerprint,sections,gaps,warnings,association};
}

/** Caller authorizes the live target before invoking this read-only materializer
 * and controls the transaction isolation. No global locks are acquired here. */
export async function materializeWorkflowSource(input: WorkflowMaterializationInput, q: Queryable): Promise<MaterializedWorkflowSource> {
  validateInput(input);
  try {
    if (input.source.kind === 'agency-response') {
      const { materializeAgencyResponseSource } = await import('./agency-response-source');
      return await materializeAgencyResponseSource({ ...input, source: input.source }, q);
    }
    if (input.source.kind === 'study-design-crf') {
      const { materializeStudyDesignCrfSource } = await import('./study-design-crf-source');
      return await materializeStudyDesignCrfSource({ ...input, source: input.source }, q);
    }
    if (input.source.kind === 'ivd-assessment' || input.source.kind === 'ivd-document') {
      const { materializeIvdWorkflowSource } = await import('./ivd-workflow-source');
      return await materializeIvdWorkflowSource({ ...input, source: input.source }, q);
    }
    const selected = { ...input, source: input.source };
    return finish(selected, input.source.kind === 'protocol' ? await composeProtocol(input, q) : await composeCsr({ ...input, source: input.source }, q));
  }
  catch (error) {
    if (error instanceof WorkflowSourceImportError) throw error;
    if (error instanceof CsrScopeError) throw new WorkflowSourceImportError(error.status,error.code,error.message);
    sourceLogger.error('Saved workflow source verification failed', { message: error instanceof Error ? error.message : 'Unknown read failure' });
    return fail(503,'WORKFLOW_SOURCE_UNAVAILABLE','The saved workflow source could not be verified. Nothing was imported.');
  }
}
